# Replace the loading-screen controller with a time-paced version. Delimiter ~.
s~\(\(\) => \{\n  const el = document\.getElementById\('siteLoader'\); if \(!el\) return;.*?requestAnimationFrame\(tick\);\n\}\)\(\);~(() => {\n  const el = document.getElementById('siteLoader'); if (!el) return;\n  const fill = el.querySelector('.sl-fill'), spill = el.querySelector('.sl-spill'), pct = el.querySelector('.sl-pct'), lbl = el.querySelector('.sl-label');\n  const reduced = window.matchMedia \&\& window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n  /* the bar runs on its own clock: at least MIN_MS from first paint to 100%, real progress can only hold it back */\n  const MIN_MS = reduced ? 600 : 3200;\n  const t0 = performance.now();\n  let real = 0.04, shown = 0.04, complete = false, finished = false, last = t0;\n  document.documentElement.classList.add('is-loading');\n  const ease = (k) => 1 - Math.pow(1 - k, 2.2);\n  const paint = () => { const w = (shown * 100).toFixed(2) + '%'; fill.style.width = w; spill.style.width = w; pct.textContent = Math.round(shown * 100) + '%'; };\n  const finish = () => { finished = true; shown = 1; paint(); if (lbl) lbl.textContent = 'Ready'; setTimeout(() => { el.classList.add('out'); document.documentElement.classList.remove('is-loading'); setTimeout(() => el.remove(), 900); }, 260); };\n  const tick = (now) => {\n    if (finished) return;\n    const dt = Math.min(0.1, Math.max(0, (now - last) / 1000)); last = now;\n    const k = Math.min(1, (now - t0) / MIN_MS);\n    const timeCap = 0.04 + 0.96 * ease(k);\n    const realCap = complete ? 1 : Math.min(0.97, real);\n    const target = Math.min(realCap, timeCap);\n    shown = reduced ? target : shown + (target - shown) * Math.min(1, dt * 9);\n    if (complete \&\& k >= 1 \&\& shown > 0.995) { finish(); return; }\n    paint();\n    requestAnimationFrame(tick);\n  };\n  window.__loading = {\n    set(f, label) { if (finished) return; real = Math.max(real, f); if (label \&\& lbl \&\& !complete) lbl.textContent = label; },\n    done() { complete = true; },\n    _debug: { tick, state: () => ({ shown, real, complete, finished, elapsed: performance.now() - t0 }) }\n  };\n  window.__loading.fail = window.__loading.done;\n  if (document.fonts \&\& document.fonts.ready) document.fonts.ready.then(() => el.classList.add('fonts'));\n  setTimeout(() => el.classList.add('fonts'), 700);\n  window.addEventListener('load', () => window.__loading.set(0.3));\n  setTimeout(() => { if (!complete \&\& real <= 0.3) { const sc = document.querySelector('.scene'); if (sc) sc.classList.add('nogl'); window.__loading.done(); } }, 12000);\n  setTimeout(() => window.__loading.done(), 30000);\n  requestAnimationFrame(tick);\n})();~s;
